const RETRYABLE = new Set([429, 502, 503, 504]);

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function fetchWithRetry(url: string, init: RequestInit, attempts = 4): Promise<Response> {
  let delay = 250;
  for (let attempt = 1; ; attempt++) {
    const res = await fetch(url, init);
    if (!RETRYABLE.has(res.status) || attempt >= attempts) {
      return res;
    }
    const retryAfter = Number(res.headers.get("retry-after"));
    await sleep(Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : delay);
    delay = Math.min(delay * 2, 4000);
  }
}

export async function fetchInvoices(page: number, signal?: AbortSignal): Promise<Invoice[]> {
  const res = await fetchWithRetry(`${BASE_URL}/invoices?page=${page}`, {
    headers: authHeaders(),
    signal,
  });
  if (!res.ok) {
    throw new ApiError(res.status, await res.text());
  }
  const body: unknown = await res.json();
  if (!Array.isArray(body)) {
    throw new ApiError(res.status, "expected an array of invoices");
  }
  return body as Invoice[];
}

export async function fetchAllInvoices(signal?: AbortSignal): Promise<Invoice[]> {
  const all: Invoice[] = [];
  for (let page = 1; page < 1000; page++) {
    const batch = await fetchInvoices(page, signal);
    if (batch.length === 0) {
      break;
    }
    all.push(...batch);
  }
  return all;
}

