terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.60"
    }
  }
}

variable "name" {
  type        = string
  description = "Bucket name, must be globally unique"
}

variable "noncurrent_days" {
  type    = number
  default = 30
}

variable "tags" {
  type    = map(string)
  default = {}
}

resource "aws_s3_bucket" "this" {
  bucket = var.name
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    id     = "expire-noncurrent"
    status = "Enabled"
    filter {}
    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_days
    }
    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "bucket_name" {
  value = aws_s3_bucket.this.bucket
}

#!/usr/bin/env python3
"""Print the largest directories under a path, without following symlinks.

Read-only: it never deletes or moves anything.
"""
import argparse
import os
import sys
from heapq import nlargest


def human(n: float) -> str:
    for unit in ("B", "K", "M", "G", "T"):
        if n < 1024:
            return f"{n:6.1f}{unit}"
        n /= 1024
    return f"{n:6.1f}P"


def walk_sizes(root: str, one_fs: bool) -> dict[str, int]:
    sizes: dict[str, int] = {}
    root_dev = os.lstat(root).st_dev
    for dirpath, dirnames, filenames in os.walk(root, topdown=True, followlinks=False):
        if one_fs:
            dirnames[:] = [d for d in dirnames
                           if os.lstat(os.path.join(dirpath, d)).st_dev == root_dev]
        total = 0
        for name in filenames:
            try:
                total += os.lstat(os.path.join(dirpath, name)).st_size
            except OSError:
                continue
        sizes[dirpath] = total
    # roll sizes up to parents
    for path in sorted(sizes, key=len, reverse=True):
        parent = os.path.dirname(path)
        if parent in sizes and parent != path:
            sizes[parent] += sizes[path]
    return sizes


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("path", nargs="?", default=".")
    ap.add_argument("-n", "--top", type=int, default=20)
    ap.add_argument("-x", "--one-file-system", action="store_true")
    ap.add_argument("--depth", type=int, default=3, help="only report directories up to this depth")
    args = ap.parse_args()

    root = os.path.abspath(args.path)
    if not os.path.isdir(root):
        print(f"not a directory: {root}", file=sys.stderr)
        return 2
    sizes = walk_sizes(root, args.one_file_system)
    base_depth = root.rstrip(os.sep).count(os.sep)
    shown = {p: s for p, s in sizes.items() if p.count(os.sep) - base_depth <= args.depth}
    for path, size in nlargest(args.top, shown.items(), key=lambda kv: kv[1]):
        print(f"{human(size)}  {os.path.relpath(path, root)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
